(()=>{'use strict';
const $=(s,ctx=document)=>ctx.querySelector(s),$$=(s,ctx=document)=>[...ctx.querySelectorAll(s)];
const intro=$('#brand-intro');if(intro){let done=false;const close=()=>{if(done)return;done=true;document.documentElement.classList.remove('intro-active');intro.remove()};
const active=document.documentElement.classList.contains('intro-active');if(active){const skip=$('#skip-intro');if(skip)skip.tabIndex=0;skip?.addEventListener('click',close);window.setTimeout(close,1250);intro.addEventListener('animationend',e=>{if(e.target===intro)close()},{once:true})}else close();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active)close()})}
const menu=$('#menu-toggle'),nav=$('#main-navigation');if(menu&&nav){const toggle=state=>{nav.classList.toggle('is-open',state);document.body.classList.toggle('menu-open',state);menu.setAttribute('aria-expanded',String(state));menu.textContent=state?'✕':'☰'};menu.addEventListener('click',()=>toggle(!nav.classList.contains('is-open')));$$('a',nav).forEach(a=>a.addEventListener('click',()=>toggle(false)));document.addEventListener('keydown',e=>{if(e.key==='Escape')toggle(false)})}
const dropdown=$('.nav-drop__toggle'),panel=$('.nav-drop__menu');if(dropdown&&panel){const navdrop=dropdown.closest('.nav-drop');const links=$$('a',panel);const set=v=>{navdrop.classList.toggle('is-open',v);dropdown.setAttribute('aria-expanded',String(v))};dropdown.addEventListener('click',()=>set(dropdown.getAttribute('aria-expanded')!=='true'));dropdown.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();set(true);(e.key==='ArrowDown'?links[0]:links[links.length-1])?.focus()}else if(e.key==='Escape')set(false)});panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();set(false);dropdown.focus();return}if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const i=links.indexOf(document.activeElement);if(e.key==='Home')links[0]?.focus();else if(e.key==='End')links[links.length-1]?.focus();else links[(i+(e.key==='ArrowDown'?1:-1)+links.length)%links.length]?.focus()});document.addEventListener('click',e=>{if(!navdrop.contains(e.target))set(false)})}
const dialog=$('#cookie-dialog'),consentKey='digitron_cookie_consent_v3';let accepted=false;
const getConsent=()=>{try{return localStorage.getItem(consentKey)}catch(e){return null}};
function initGa4(){const id=$('meta[name="digitron-ga4-id"]')?.content;if(!id||!/^G-[A-Z0-9]+$/i.test(id)||id==='G-XXXXXXXXXX'||window.__digitronAnalyticsStarted)return;window.__digitronAnalyticsStarted=true;window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments)};window.gtag('js',new Date());window.gtag('config',id,{send_page_view:true});const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(id);document.head.appendChild(s)}
function consent(v){accepted=v==='accepted';try{localStorage.setItem(consentKey,v)}catch(e){}dialog?.classList.remove('is-visible');dialog?.setAttribute('aria-hidden','true');if(accepted)initGa4()}
if(getConsent()==='accepted'){accepted=true;initGa4()}else if(!getConsent()){dialog?.classList.add('is-visible');dialog?.setAttribute('aria-hidden','false')}
$('#accept-cookies')?.addEventListener('click',()=>consent('accepted'));$('#reject-cookies')?.addEventListener('click',()=>consent('rejected'));$$('[data-cookie-settings]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();dialog?.classList.add('is-visible');dialog?.setAttribute('aria-hidden','false')}));
function event(name,params){if(accepted&&window.gtag)window.gtag('event',name,params||{})}
$$('a[href^="tel:"]').forEach(a=>a.addEventListener('click',()=>event('click_phone',{link_url:a.href})));$$('a[href^="mailto:"]').forEach(a=>a.addEventListener('click',()=>event('click_email',{link_url:a.href})));
const cards=$$('[data-product]'),filter=$('#product-filter'),query=$('#product-search'),counter=$('#product-count'),empty=$('#no-results');function filterProducts(){const cat=filter?.value||'all',term=(query?.value||'').toLocaleLowerCase('hr').trim();let total=0;cards.forEach(c=>{const yes=(cat==='all'||cat===c.dataset.group)&&(!term||c.dataset.search.toLocaleLowerCase('hr').includes(term));c.hidden=!yes;if(yes)total++});if(counter)counter.textContent=total;if(empty)empty.style.display=total?'none':'block'}filter?.addEventListener('change',filterProducts);query?.addEventListener('input',filterProducts);if(cards.length)filterProducts();
const chosen=new URLSearchParams(location.search).get('vrsta'),sel=$('#vrsta');if(sel&&chosen&&[...sel.options].some(o=>o.value===chosen))sel.value=chosen;
$$('.digitron-form').forEach(form=>{const feedback=$('.form-feedback',form),subject=$('input[name="subject"]',form),section=$('input[name="odjel"]',form),type=$('select[name="vrsta"]',form);function update(){const v=type?.value||subject?.value||'Opći upit',service=/servis|ovjera|blagajn/i.test(v)&&!/Proizvod/i.test(v);if(section)section.value=service?'servis@digitron.hr':'prodaja@digitron.hr';if(subject)subject.value='Digitron — '+v}type?.addEventListener('change',update);update();
form.addEventListener('submit',async e=>{e.preventDefault();feedback.textContent='';$$('[aria-invalid="true"]',form).forEach(el=>el.removeAttribute('aria-invalid'));let first=null;$$('input,textarea,select',form).forEach(el=>{if(!el.checkValidity()&&!el.disabled&&el.type!=='hidden'&&!el.classList.contains('botcheck')){el.setAttribute('aria-invalid','true');if(!first)first=el}});if(first){feedback.textContent='Provjerite obvezna polja i ispravnost e-mail adrese.';first.focus();return}
const submit=$('button[type="submit"]',form);submit.disabled=true;submit.textContent='Šaljem upit…';try{const res=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}});const data=await res.json();if(!res.ok||!data.success)throw new Error('Server nije potvrdio slanje');event('generate_lead',{form_name:form.id});location.href='hvala.html'}catch(err){feedback.textContent='Upit nije moguće poslati. Pokušajte ponovno ili nam pišite na prodaja@digitron.hr.';submit.disabled=false;submit.textContent='Pošaljite upit'}})});
$$('[data-show-map]').forEach(b=>b.addEventListener('click',()=>{const box=b.closest('[data-map]');if(!box)return;if(!accepted){const ok=window.confirm('Za prikaz Google karte potrebno je dopustiti učitavanje vanjskog sadržaja. Želite li prihvatiti i učitati kartu?');if(!ok)return;consent('accepted')}const f=document.createElement('iframe');f.loading='lazy';f.referrerPolicy='no-referrer-when-downgrade';f.title='Digitron Buje — Google karta';f.src=box.dataset.map;box.replaceChildren(f)}));
const revealed=$$('.reveal');if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target)}}),{threshold:.07});revealed.forEach(x=>io.observe(x))}else revealed.forEach(x=>x.classList.add('is-visible'));
})();